'use strict';
const shades=[{"id":"brown","label":"بني","en":"BROWN","hex":"#804324"},{"id":"golden-yellow","label":"أصفر ذهبي","en":"GOLDEN YELLOW","hex":"#dda518"},{"id":"gray","label":"رمادي","en":"GRAY","hex":"#858990"},{"id":"green","label":"أخضر","en":"GREEN","hex":"#14732d"},{"id":"purple","label":"موف","en":"PURPLE","hex":"#8420a3"},{"id":"blue","label":"أزرق","en":"BLUE","hex":"#175bd2"},{"id":"blue-black","label":"أسود مزرق","en":"BLUE BLACK","hex":"#123452"},{"id":"black","label":"أسود","en":"BLACK","hex":"#242429"},{"id":"burgundy","label":"أحمر نبيتي","en":"BURGUNDY","hex":"#8a153a"},{"id":"fiery-red","label":"أحمر ناري","en":"FIERY RED","hex":"#da241d"}];
const $=s=>document.querySelector(s);const money=n=>new Intl.NumberFormat('ar-EG',{maximumFractionDigits:0}).format(n)+' ج.م';
const products=shades.map(s=>({id:'shade-'+s.id,name:'كارين كريزي كولور — '+s.label,en:s.en,category:'color',shade:s.label,image:'assets/colors/'+s.id+'.jpg',price:100,keywords:'لون الوان شعر صبغة صبغه كريزي كولور '+s.label+' '+s.en})).concat([{id:'leave-in',name:'كريم Leave In',en:'LEAVE-IN CREAM',category:'care',keywords:'كريم شيا ليف ان عناية شعر',description:'مع زبدة الشيا، كما يظهر على العبوة في صورة المجموعة.'},{id:'hair-powder',name:'بودرة الشعر',en:'HAIR POWDER',category:'style',keywords:'بودرة بودره تصفيف شعر',description:'بودرة الشعر الظاهرة في صورة المجموعة. تفاصيل الاستخدام قيد الاستكمال.'}]);
function safeLoad(key,fallback){try{const value=JSON.parse(localStorage.getItem(key));return value===null?fallback:value;}catch{return fallback;}}
let saved=safeLoad('karin-atelier-favorites',[]);saved=Array.isArray(saved)?[...new Set(saved.filter(id=>products.some(p=>p.id===id)))]:[];
let cart=safeLoad('karin-color-cart',[]);cart=Array.isArray(cart)?cart.filter(x=>x&&products.some(p=>p.id===x.id&&p.price)&&Number.isInteger(x.qty)&&x.qty>0&&x.qty<=20).reduce((acc,x)=>{const old=acc.find(y=>y.id===x.id);if(old)old.qty=Math.min(20,old.qty+x.qty);else acc.push({id:x.id,qty:x.qty});return acc;},[]):[];
let selectedShade='purple',quantity=1,filter='color',toastTimer;
const normalize=s=>s.toLowerCase().normalize('NFD').replace(/[\u064B-\u065F\u0670]/g,'').replace(/[أإآ]/g,'ا').replace(/ى/g,'ي').replace(/ة/g,'ه');
function persist(){try{localStorage.setItem('karin-color-cart',JSON.stringify(cart));localStorage.setItem('karin-atelier-favorites',JSON.stringify(saved));}catch{}}
function notify(message){$('#toast').textContent=message;$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),2400);}
function getProduct(id){return products.find(p=>p.id===id);}
function sync(){document.querySelectorAll('.cart-count').forEach(e=>e.textContent=cart.reduce((n,x)=>n+x.qty,0));document.querySelectorAll('[data-save]').forEach(b=>{const p=getProduct(b.dataset.save);if(!p)return;const active=saved.includes(p.id);b.setAttribute('aria-pressed',String(active));b.setAttribute('aria-label',(active?'إزالة ':'حفظ ')+p.name+(active?' من الاختيارات':' في الاختيارات'));});const active=saved.includes('shade-'+selectedShade);$('#saveSelected').textContent=active?'محفوظ في اختياراتك ♥':'احفظ اللون ♡';$('#saveSelected').setAttribute('aria-pressed',String(active));const detailSave=$('#detailSave');if(detailSave){const active=saved.includes(detailSave.dataset.save);detailSave.textContent=active?'إزالة من الاختيارات ♥':'احفظ الاختيار ♡';}persist();}
function changeShade(id){const s=shades.find(s=>s.id===id);if(!s)return;selectedShade=id;const image=$('#shadeImage');image.src='assets/colors/'+id+'.jpg';image.alt='صورة إعلان كارين بدرجة '+s.label;$('#shadeName').textContent=s.label;$('#selectedName').textContent=s.label;$('#shadeEnglish').textContent=s.en;$('#shadePosition').textContent=String(shades.indexOf(s)+1).padStart(2,'0')+' / 10';document.querySelectorAll('[data-shade]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.shade===id)));sync();}
function addToCart(id,qty=1){const p=getProduct(id);if(!p||!p.price)return;const existing=cart.find(x=>x.id===id);if(existing&&existing.qty+qty>20){notify('الحد الأقصى 20 عبوة من نفس الدرجة.');return;}if(existing)existing.qty+=qty;else cart.push({id,qty});sync();notify('اتضاف للسلة: '+p.shade+' × '+qty);renderCart();}
function toggleSaved(id){if(!getProduct(id))return;const exists=saved.includes(id);saved=exists?saved.filter(x=>x!==id):[...saved,id];sync();if($('#savedDialog').open)renderSaved();notify(exists?'اتشال من اختياراتك':'اتحفظ في اختياراتك ♥');}
function legacyImage(p){return `<div class="legacy-media"><img class="legacy-art ${p.category}" src="assets/collection.jpeg" width="447" height="447" alt="${p.name} من صورة المجموعة" loading="lazy"></div>`;}
function renderProducts(){const term=normalize($('#search').value.trim());let list=products.filter(p=>(filter==='all'||filter===p.category)&&normalize(p.name+' '+p.keywords).includes(term));if($('#sort').value==='name')list.sort((a,b)=>a.name.localeCompare(b.name,'ar'));$('#products').innerHTML=list.map(p=>`<article class="product"><div class="card-media">${p.image?`<img src="${p.image}" width="1254" height="1254" alt="صورة إعلان درجة ${p.shade}" loading="lazy">`:legacyImage(p)}<button class="save-btn" data-save="${p.id}" aria-pressed="false" aria-label="حفظ ${p.name} في الاختيارات">♡</button></div><div class="card-top"><span>${p.en}</span><strong>${p.price?money(p.price):'السعر يُضاف لاحقًا'}</strong></div><h3>${p.shade||p.name}</h3><button class="card-cta" data-product="${p.id}">${p.shade?'اختار Color':'اكتشف المنتج'} <span>↗</span></button></article>`).join('');$('#resultCount').textContent=list.length+' اختيار من '+products.length;$('#empty').hidden=!!list.length;sync();}
function setFilter(value){filter=value;document.querySelectorAll('[data-filter]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.filter===value)));renderProducts();}
function openProduct(id){const p=getProduct(id);if(!p)return;const options=p.shade?`<label class="color-select-label" for="detailColor">Color / اللون</label><select id="detailColor">${shades.map(s=>`<option value="shade-${s.id}" ${p.id==='shade-'+s.id?'selected':''}>${s.label}</option>`).join('')}</select>`:'';$('#productDetail').innerHTML=`<div class="product-detail"><div class="detail-image">${p.image?`<img src="${p.image}" alt="الصورة الإعلانية لدرجة ${p.shade}" width="1254" height="1254">`:legacyImage(p)}</div><div class="detail-copy"><span class="eyebrow">KARIN / ${p.en}</span><h2 id="detailTitle">${p.shade?'كريزي كولور — '+p.shade:p.name}</h2><strong class="detail-price">${p.price?money(p.price):'السعر قيد الاعتماد'}</strong><p>${p.shade?'اختار اللون من القائمة، وضيف نفس الدرجة للسلة.':'تفاصيل المنتج كما تظهر في صورة المجموعة.'}</p>${options}<dl><div><dt>الشحن</dt><dd>لكل مصر · التكلفة تُحدّد لاحقًا</dd></div><div><dt>التوافر والمواصفات</dt><dd>يُؤكّدان قبل الطلب</dd></div></dl>${p.price?`<button class="button lime" data-add="${p.id}">أضف للسلة <span>↗</span></button>`:''}<button class="text-button" id="detailSave" data-save="${p.id}" aria-pressed="false">احفظ الاختيار ♡</button><p class="detail-note">${p.shade?'صورة إعلانية للإلهام، وليست ضمانًا لنتيجة الاستخدام.':'المواصفات وطريقة الاستخدام تُضاف بعد اعتمادها.'} تأكيد الطلب والدفع غير متاحين بعد.</p></div></div>`;sync();if(!$('#productDialog').open)$('#productDialog').showModal();}
function renderCart(){const el=$('#cartItems');el.innerHTML=cart.length?cart.map(item=>{const p=getProduct(item.id);return `<article class="cart-item"><img src="${p.image}" alt="درجة ${p.shade}" width="1254" height="1254"><div><span class="eyebrow">KARIN COLOR</span><h3>${p.shade}</h3><p>${money(p.price)} / عبوة</p><div class="cart-item-bottom"><div class="quantity"><button data-cart-minus="${p.id}" aria-label="تقليل كمية ${p.shade}">−</button><output>${item.qty}</output><button data-cart-plus="${p.id}" aria-label="زيادة كمية ${p.shade}">+</button></div><strong>${money(item.qty*p.price)}</strong></div></div><button class="remove" data-remove="${p.id}" aria-label="حذف ${p.shade} من السلة">×</button></article>`;}).join(''):'<div class="empty"><h3>السلة مستنية مودك.</h3><p>اختار اللون واضغط «أضف للسلة».</p></div>';$('#cartSubtotal').textContent=money(cart.reduce((n,x)=>n+x.qty*getProduct(x.id).price,0));$('#reviewOrder').disabled=!cart.length;sync();}
function showCart(){renderCart();$('#cartDialog').showModal();}
function renderSaved(){$('#savedItems').innerHTML=saved.length?saved.map(id=>{const p=getProduct(id);return `<div class="saved-row"><div><h3>${p.shade||p.name}</h3><p>${p.price?money(p.price):'السعر قيد الاعتماد'}</p></div><button class="text-button" data-saved-product="${p.id}">التفاصيل ↗</button><button class="remove" data-unsave="${p.id}" aria-label="إزالة ${p.shade||p.name} من الاختيارات">×</button></div>`;}).join(''):'<div class="empty"><h3>إيه اللون اللي لفتك؟</h3><p>احفظه بالقلب وارجع له في أي وقت.</p></div>';}
function reviewOrder(){if(!cart.length)return;$('#cartDialog').close();$('#orderSummary').innerHTML=cart.map(x=>{const p=getProduct(x.id);return `<div class="order-row"><span>${p.shade} × ${x.qty}</span><strong>${money(x.qty*p.price)}</strong></div>`;}).join('')+`<div class="order-row total"><span>إجمالي المنتجات</span><strong>${money(cart.reduce((n,x)=>n+x.qty*getProduct(x.id).price,0))}</strong></div><div class="order-row"><span>الشحن لكل مصر</span><span>التكلفة لم تُحدّد بعد</span></div><p class="purchase-note">السعر النهائي يشمل الشحن عند اعتماده. لا توجد أي دفعة أو طلب مؤكد الآن.</p>`;$('#checkoutDialog').showModal();}
function openSearch(open){$('#searchPanel').hidden=!open;$('#searchToggle').setAttribute('aria-expanded',String(open));if(open)$('#search').focus();else $('#searchToggle').focus();}
$('#shadeSwatches').innerHTML=shades.map(s=>`<button class="shade-swatch" data-shade="${s.id}" aria-label="اختيار لون ${s.label}" aria-pressed="false"><i style="--swatch:${s.hex}"></i><span>${s.label}</span></button>`).join('');
document.addEventListener('click',e=>{const find=a=>e.target.closest(a);let b;if(b=find('[data-shade]'))changeShade(b.dataset.shade);if(b=find('[data-pick-shade]')){changeShade(b.dataset.pickShade);$('#colorStudio').scrollIntoView();}if(b=find('[data-save]'))toggleSaved(b.dataset.save);if(b=find('[data-product]'))openProduct(b.dataset.product);if(b=find('[data-add]'))addToCart(b.dataset.add,1);if(b=find('[data-open-cart]'))showCart();if(b=find('[data-open-saved]')){renderSaved();$('#savedDialog').showModal();}if(b=find('[data-saved-product]')){$('#savedDialog').close();openProduct(b.dataset.savedProduct);}if(b=find('[data-unsave]'))toggleSaved(b.dataset.unsave);if(b=find('[data-remove]')){cart=cart.filter(x=>x.id!==b.dataset.remove);renderCart();}if(b=find('[data-cart-plus]')){const item=cart.find(x=>x.id===b.dataset.cartPlus);if(item&&item.qty<20)item.qty++;else notify('الحد الأقصى 20 عبوة من نفس الدرجة.');renderCart();}if(b=find('[data-cart-minus]')){const item=cart.find(x=>x.id===b.dataset.cartMinus);if(item&&item.qty>1)item.qty--;renderCart();}if(b=find('[data-filter]'))setFilter(b.dataset.filter);});
document.addEventListener('change',e=>{if(e.target.id==='detailColor')openProduct(e.target.value);});
$('#qtyMinus').onclick=()=>{quantity=Math.max(1,quantity-1);$('#quantity').textContent=quantity;};$('#qtyPlus').onclick=()=>{quantity=Math.min(20,quantity+1);$('#quantity').textContent=quantity;};$('#addSelected').onclick=()=>addToCart('shade-'+selectedShade,quantity);$('#saveSelected').onclick=()=>toggleSaved('shade-'+selectedShade);$('#viewSelected').onclick=()=>openProduct('shade-'+selectedShade);$('#searchToggle').onclick=()=>openSearch($('#searchPanel').hidden);$('#searchClose').onclick=()=>openSearch(false);$('#search').oninput=()=>setFilter('all');$('#search').onkeydown=e=>{if(e.key==='Enter'){openSearch(false);$('#shop').scrollIntoView();}if(e.key==='Escape')openSearch(false);};$('#sort').onchange=renderProducts;$('#resetSearch').onclick=()=>{$('#search').value='';setFilter('all');};document.querySelectorAll('.close').forEach(b=>b.onclick=()=>b.closest('dialog').close());$('#reviewOrder').onclick=reviewOrder;$('#keepShopping').onclick=()=>{$('#cartDialog').close();$('#colorStudio').scrollIntoView();};$('#backToCart').onclick=()=>{$('#checkoutDialog').close();showCart();};$('#year').textContent=new Date().getFullYear();$('#shadePrice').textContent=money(100)+' / عبوة';changeShade(selectedShade);renderProducts();sync();
